package com.bookstore.config; import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.core.userdetails.*; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.provisioning.InMemoryUserDetailsManager; import org.springframework.security.web.SecurityFilterChain; @Configuration public class SecurityConfig{ @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();} @Bean UserDetailsService users(PasswordEncoder e){UserDetails admin=User.withUsername("admin").password(e.encode("admin123")).roles("ADMIN").build();UserDetails staff=User.withUsername("staff").password(e.encode("staff123")).roles("STAFF").build();return new InMemoryUserDetailsManager(admin,staff);} @Bean SecurityFilterChain chain(HttpSecurity h)throws Exception{h.authorizeHttpRequests(a->a.requestMatchers("/css/**","/login","/error").permitAll().requestMatchers("/**/delete/**").hasRole("ADMIN").anyRequest().hasAnyRole("ADMIN","STAFF")).formLogin(f->f.loginPage("/login").defaultSuccessUrl("/dashboard",true).permitAll()).logout(l->l.logoutSuccessUrl("/login?logout"));return h.build();}}